import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test6_executable';
const SENT = 'ZqSENTINELqZ';
const SENT_OUT = '<p>' + SENT + '</p>\n';
const cases = readFileSync(process.argv[2], 'utf8').split('\n').filter(l => l.trim() !== '')
  .map(l => { const v = JSON.parse(l); return typeof v === 'string' ? { label: v, text: v } : v; });
for (const c of cases) {
  const r = spawnSync(EXE, ['--a=' + c.text, '--b=' + SENT], { encoding: 'utf8', maxBuffer: 1 << 26 });
  console.log('### ' + JSON.stringify(c.label));
  console.log('IN  ' + JSON.stringify(c.text));
  if (r.status !== 0) console.log('RC  ' + r.status + '  ERR ' + JSON.stringify(r.stderr));
  else { const i = r.stdout.lastIndexOf(SENT_OUT); console.log('OUT ' + JSON.stringify(i >= 0 ? r.stdout.slice(0, i) : r.stdout)); }
}
